import sys

def main():
    queries = []
    for i in range(30):
        queries.append((i, 0))
        queries.append((0, i))
        queries.append((i, i))

    answers = []
    for c, d in queries:
        print(f"? {c} {d}")
        sys.stdout.flush()
        answer = int(input())
        if answer == -2:
            return
        answers.append(answer)

    a = 0
    b = 0
    for i in range(30):
        if answers[i] == 1:
            a |= (1 << i)
        if answers[i + 30] == -1:
            b |= (1 << i)
        if answers[i + 60] == 0:
            a |= (1 << i)
            b |= (1 << i)

    print(f"! {a} {b}")
    sys.stdout.flush()

if __name__ == "__main__":
    main()
